def is_ipv4(s):
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        # Check for leading zeros (e.g., "01") and range 0-255
        if (len(part) > 1 and part[0] == '0') or not (0 <= int(part) <= 255):
            return False
    return True
